import { sql } from 'drizzle-orm';
import {sqliteTable, text, integer, real, index, uniqueIndex} from 'drizzle-orm/sqlite-core';

/**
 * CRA Compliance OS — relational schema.
 *
 * Conventions
 * - All ids are opaque text (`<prefix>_<nanoid>`), generated by the application.
 * - All timestamps are integer epoch **milliseconds in UTC**. The product never
 *   stores local time; rendering is localised in the UI.
 * - Every tenant-owned table carries `orgId` and must be queried with an
 *   explicit `orgId` predicate. See `src/core/tenant.ts` and the isolation test
 *   in `tests/unit/tenant-isolation.test.ts`.
 * - Money is stored in minor units (cents) as integers. Credits are integers.
 */

const now = sql`(unixepoch() * 1000)`;

// ---------------------------------------------------------------------------
// Identity & access
// ---------------------------------------------------------------------------

export const users = sqliteTable(
  'users',
  {
    id: text('id').primaryKey(),
    email: text('email').notNull(),
    emailNormalised: text('email_normalised').notNull(),
    name: text('name'),
    avatarUrl: text('avatar_url'),
    passwordHash: text('password_hash'),
    emailVerifiedAt: integer('email_verified_at'),
    isSystemAdmin: integer('is_system_admin', { mode: 'boolean' }).notNull().default(false),
    status: text('status', { enum: ['active', 'suspended', 'deleted'] })
      .notNull()
      .default('active'),
    lastLoginAt: integer('last_login_at'),
    defaultOrgId: text('default_org_id'),
    timezone: text('timezone').default('UTC'),
    locale: text('locale').default('en'),
    createdAt: integer('created_at').notNull().default(now),
    updatedAt: integer('updated_at').notNull().default(now),
    deletedAt: integer('deleted_at'),
  },
  (t) => [
    uniqueIndex('users_email_normalised_uq').on(t.emailNormalised),
    index('users_status_idx').on(t.status),
  ],
);

/** OAuth / external identities linked to a user (GitHub, GitLab, ...). */
export const identities = sqliteTable(
  'identities',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    provider: text('provider').notNull(),
    providerAccountId: text('provider_account_id').notNull(),
    providerLogin: text('provider_login'),
    /** Encrypted at rest with AES-256-GCM (see core/crypto.ts). Never returned by the API. */
    accessTokenEnc: text('access_token_enc'),
    refreshTokenEnc: text('refresh_token_enc'),
    tokenExpiresAt: integer('token_expires_at'),
    scope: text('scope'),
    profileJson: text('profile_json'),
    createdAt: integer('created_at').notNull().default(now),
    updatedAt: integer('updated_at').notNull().default(now),
  },
  (t) => [uniqueIndex('identities_provider_uq').on(t.provider, t.providerAccountId), index('identities_user_idx').on(t.userId)],
);

export const sessions = sqliteTable(
  'sessions',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull(),
    ip: text('ip'),
    userAgent: text('user_agent'),
    expiresAt: integer('expires_at').notNull(),
    lastUsedAt: integer('last_used_at').notNull().default(now),
    revokedAt: integer('revoked_at'),
    createdAt: integer('created_at').notNull().default(now),
  },
  (t) => [uniqueIndex('sessions_token_hash_uq').on(t.tokenHash), index('sessions_user_idx').on(t.userId), index('sessions_expires_idx').on(t.expiresAt)],
);

export const magicLinks = sqliteTable(
  'magic_links',
  {
    id: text('id').primaryKey(),
    email: text('email').notNull(),
    tokenHash: text('token_hash').notNull(),
    redirectTo: text('redirect_to'),
    expiresAt: integer('expires_at').notNull(),
    consumedAt: integer('consumed_at'),
    createdAt: integer('created_at').notNull().default(now),
  },
  (t) => [uniqueIndex('magic_links_token_hash_uq').on(t.tokenHash), index('magic_links_email_idx').on(t.email)],
);

// ---------------------------------------------------------------------------
// Tenancy
// ---------------------------------------------------------------------------

export const organizations = sqliteTable(
  'organizations',
  {
    id: text('id').primaryKey(),
    name: text('name').notNull(),
    slug: text('slug').notNull(),
    /** Commercial plan key; resolves through the pricing tables. */
    planKey: text('plan_key').notNull().default('free'),
    billingEmail: text('billing_email'),
    country: text('country'),
    vatId: text('vat_id'),
    companyLegalName: text('company_legal_name'),
    /** Agency / partner model: a parent org (consultancy) managing this one. */
    parentOrgId: text('parent_org_id'),
    isAgency: integer('is_agency', { mode: 'boolean' }).notNull().default(false),
    autoTopupEnabled: integer('auto_topup_enabled', { mode: 'boolean' }).notNull().default(false),
    autoTopupThresholdCredits: integer('auto_topup_threshold_credits').notNull().default(100),
    autoTopupPackKey: text('auto_topup_pack_key'),
    retentionDays: integer('retention_days').notNull().default(365),
    currency: text('currency').notNull().default('USD'),
    seats: integer('seats').notNull().default(5),
    status: text('status', { enum: ['active', 'suspended', 'deleted'] }).notNull().default('active'),
    createdAt: integer('created_at').notNull().default(now),
    updatedAt: integer('updated_at').notNull().default(now),
    deletedAt: integer('deleted_at'),
  },
  (t) => [
    uniqueIndex('organizations_slug_uq').on(t.slug),
    index('organizations_parent_idx').on(t.parentOrgId),
    index('organizations_status_idx').on(t.status),
  ],
);

export const organizationMembers = sqliteTable(
  'organization_members',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    role: text('role', { enum: ['owner', 'admin', 'member', 'viewer'] })
      .notNull()
      .default('member'),
    invitedByUserId: text('invited_by_user_id'),
    createdAt: integer('created_at').notNull().default(now),
    updatedAt: integer('updated_at').notNull().default(now),
  },
  (t) => [
    uniqueIndex('organization_members_uq').on(t.orgId, t.userId),
    index('organization_members_user_idx').on(t.userId),
    index('organization_members_org_role_idx').on(t.orgId, t.role),
  ],
);

export const invites = sqliteTable(
  'invites',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    email: text('email').notNull(),
    role: text('role', { enum: ['owner', 'admin', 'member', 'viewer'] }).notNull(),
    tokenHash: text('token_hash').notNull(),
    invitedByUserId: text('invited_by_user_id'),
    expiresAt: integer('expires_at').notNull(),
    acceptedAt: integer('accepted_at'),
    revokedAt: integer('revoked_at'),
    createdAt: integer('created_at').notNull().default(now),
  },
  (t) => [uniqueIndex('invites_token_hash_uq').on(t.tokenHash), index('invites_org_idx').on(t.orgId)],
);

