/** An installed GitHub App / GitLab connection owned by the organisation. */
export const integrations = sqliteTable(
  'integrations',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    provider: text('provider', { enum: ['github', 'gitlab'] }).notNull(),
    installationId: text('installation_id').notNull(),
    accountLogin: text('account_login'),
    accountType: text('account_type'),
    permissionsJson: text('permissions_json'),
    /** 'active' | 'revoked' | 'suspended' */
    status: text('status').notNull().default('active'),
    createdAt: integer('created_at').notNull().default(now),
    updatedAt: integer('updated_at').notNull().default(now),
    revokedAt: integer('revoked_at'),
  },
  (t) => [uniqueIndex('integrations_provider_install_uq').on(t.provider, t.installationId), index('integrations_org_idx').on(t.orgId)],
);

export const projects = sqliteTable(
  'projects',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    slug: text('slug').notNull(),
    description: text('description'),
    /** A "product" in CRA terms: the thing you place on the EU market. */
    productName: text('product_name'),
    productVersion: text('product_version'),
    supportPeriodMonths: integer('support_period_months'),
    createdAt: integer('created_at').notNull().default(now),
    updatedAt: integer('updated_at').notNull().default(now),
    deletedAt: integer('deleted_at'),
  },
  (t) => [uniqueIndex('projects_org_slug_uq').on(t.orgId, t.slug), index('projects_org_idx').on(t.orgId)],
);

export const repositories = sqliteTable(
  'repositories',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    projectId: text('project_id').references(() => projects.id, { onDelete: 'set null' }),
    integrationId: text('integration_id').references(() => integrations.id, { onDelete: 'set null' }),
    provider: text('provider', { enum: ['github', 'gitlab', 'upload', 'other'] })
      .notNull()
      .default('github'),
    externalId: text('external_id'),
    owner: text('owner'),
    name: text('name').notNull(),
    fullName: text('full_name'),
    defaultBranch: text('default_branch'),
    url: text('url'),
    visibility: text('visibility'),
    lastScanId: text('last_scan_id'),
    lastScanAt: integer('last_scan_at'),
    /** Content fingerprint of the dependency manifests — lets us skip no-op scans. */
    fingerprint: text('fingerprint'),
    monitoringEnabled: integer('monitoring_enabled', { mode: 'boolean' }).notNull().default(false),
    schedule: text('schedule').default('daily'),
    badgeEnabled: integer('badge_enabled', { mode: 'boolean' }).notNull().default(false),
    badgeToken: text('badge_token'),
    readinessScore: real('readiness_score'),
    openCritical: integer('open_critical').notNull().default(0),
    openHigh: integer('open_high').notNull().default(0),
    openKev: integer('open_kev').notNull().default(0),
    status: text('status', { enum: ['active', 'error', 'paused', 'deleted'] }).notNull().default('active'),
    lastError: text('last_error'),
    createdAt: integer('created_at').notNull().default(now),
    updatedAt: integer('updated_at').notNull().default(now),
    deletedAt: integer('deleted_at'),
  },
  (t) => [
    index('repositories_org_idx').on(t.orgId, t.status),
    index('repositories_project_idx').on(t.projectId),
    uniqueIndex('repositories_badge_token_uq').on(t.badgeToken),
  ],
);

export const scans = sqliteTable(
  'scans',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    repositoryId: text('repository_id')
      .notNull()
      .references(() => repositories.id, { onDelete: 'cascade' }),
    jobId: text('job_id'),
    trigger: text('trigger', { enum: ['manual', 'push', 'schedule', 'api', 'action', 'onboarding'] })
      .notNull()
      .default('manual'),
    ref: text('ref'),
    commitSha: text('commit_sha'),
    status: text('status', { enum: ['queued', 'running', 'succeeded', 'failed', 'cancelled', 'skipped'] })
      .notNull()
      .default('queued'),
    fingerprint: text('fingerprint'),
    skippedReason: text('skipped_reason'),
    ecosystemsJson: text('ecosystems_json'),
    manifestsJson: text('manifests_json'),
    componentCount: integer('component_count').notNull().default(0),
    vulnerabilityCount: integer('vulnerability_count').notNull().default(0),
    criticalCount: integer('critical_count').notNull().default(0),
    highCount: integer('high_count').notNull().default(0),
    mediumCount: integer('medium_count').notNull().default(0),
    lowCount: integer('low_count').notNull().default(0),
    kevCount: integer('kev_count').notNull().default(0),
    readinessScore: real('readiness_score'),
    durationMs: integer('duration_ms'),
    /** Latest human-readable progress line, so the UI never renders a fake bar. */
    progressPct: integer('progress_pct').notNull().default(0),
    progressMessage: text('progress_message'),
    creditsCharged: integer('credits_charged').notNull().default(0),
    errorCode: text('error_code'),
    errorMessage: text('error_message'),
    startedAt: integer('started_at'),
    finishedAt: integer('finished_at'),
    createdAt: integer('created_at').notNull().default(now),
  },
  (t) => [
    index('scans_repo_idx').on(t.repositoryId, t.createdAt),
    index('scans_org_idx').on(t.orgId, t.createdAt),
    index('scans_status_idx').on(t.status),
  ],
);

// ---------------------------------------------------------------------------
