export const creditAccounts = sqliteTable(
  'credit_accounts',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id')
      .notNull()
      .references(() => organizations.id, { onDelete: 'cascade' }),
    balance: integer('balance').notNull().default(0),
    lifetimePurchased: integer('lifetime_purchased').notNull().default(0),
    lifetimeGranted: integer('lifetime_granted').notNull().default(0),
    lifetimeConsumed: integer('lifetime_consumed').notNull().default(0),
    currency: text('currency').notNull().default('USD'),
    /** Bumped on every write; guards against lost updates under concurrency. */
    revision: integer('revision').notNull().default(0),
    createdAt: integer('created_at').notNull().default(now),
    updatedAt: integer('updated_at').notNull().default(now),
  },
  (t) => [uniqueIndex('credit_accounts_org_uq').on(t.orgId)],
);

export const creditTransactions = sqliteTable(
  'credit_transactions',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id').notNull(),
    accountId: text('account_id')
      .notNull()
      .references(() => creditAccounts.id, { onDelete: 'cascade' }),
    type: text('type', {
      enum: ['purchase', 'grant', 'promo', 'bonus', 'referral', 'reservation', 'commit', 'release', 'refund', 'expiry', 'adjustment'],
    }).notNull(),
    /** Signed: positive credits the account, negative debits it. */
    amount: integer('amount').notNull(),
    balanceAfter: integer('balance_after').notNull(),
    referenceType: text('reference_type'),
    referenceId: text('reference_id'),
    description: text('description'),
    expiresAt: integer('expires_at'),
    createdByUserId: text('created_by_user_id'),
    /** Unique per logical operation — makes all billing writes idempotent. */
    idempotencyKey: text('idempotency_key'),
    createdAt: integer('created_at').notNull().default(now),
  },
  (t) => [
    uniqueIndex('credit_tx_idem_uq').on(t.idempotencyKey),
    index('credit_tx_account_idx').on(t.accountId, t.createdAt),
    index('credit_tx_org_idx').on(t.orgId, t.createdAt),
    index('credit_tx_ref_idx').on(t.referenceType, t.referenceId),
  ],
);

