/** Durable background job queue with retries, backoff and a dead-letter state. */
export const jobs = sqliteTable(
  'jobs',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id'),
    type: text('type').notNull(),
    payloadJson: text('payload_json').notNull(),
    status: text('status', { enum: ['pending', 'running', 'succeeded', 'failed', 'cancelled', 'dead'] })
      .notNull()
      .default('pending'),
    attempts: integer('attempts').notNull().default(0),
    maxAttempts: integer('max_attempts').notNull().default(5),
    /** Deduplication key; only one pending/running job per key at a time. */
    dedupeKey: text('dedupe_key'),
    runAt: integer('run_at').notNull().default(now),
    startedAt: integer('started_at'),
    finishedAt: integer('finished_at'),
    progressPct: integer('progress_pct').notNull().default(0),
    progressMessage: text('progress_message'),
    lastError: text('last_error'),
    resultJson: text('result_json'),
    createdAt: integer('created_at').notNull().default(now),
  },
  (t) => [
    index('jobs_status_runat_idx').on(t.status, t.runAt),
    index('jobs_org_idx').on(t.orgId),
    index('jobs_dedupe_idx').on(t.dedupeKey),
  ],
);

